export const BODY: string = "\n<p>تصویر کو 100KB تک کم کرنا پانچ منٹ کا کام ہے جب آپ درست مراحل پر عمل کریں۔ عمل سادہ ہے، مگر تفصیل طے کرتی ہے کہ نتیجہ اچھا لگے گا یا نہیں۔</p>\n<p>یہ رہنما مکمل ورک فلو بتاتا ہے۔ آپ درست ماخذ فائل چنیں گے، بہترین فارمیٹ چنیں گے، کمپریشن چلائیں گے اور استعمال سے پہلے نتیجہ کی تصدیق کریں گے۔</p>\n<p>یہ ریزیوم، ملازمت پورٹل، بلاگ تصویروں اور ای میل گرافکس کے لیے کام کرتا ہے، لیپ ٹاپ یا فون پر۔</p>\n<h2 id=\"what-you-need\">شروع کرنے سے پہلے آپ کو کیا چاہیے</h2>\n<p>آپ کو اصل تصویر فائل چاہیے۔ کیمرہ رول کی تصویر مثالی ہے؛ چیٹ ایپ سے آگے بھیجی گئی کاپی پہلے سے خراب ہے۔</p>\n<p>جانچیں کہ تصویر کہاں استعمال ہو گی۔ ریزیوم پورٹل شاید صرف JPG قبول کرے، جبکہ بلاگ WebP بھی قبول کرتا ہے۔</p>\n<p>اگر کوئی ابعاد بیان ہوں تو انہیں نوٹ کریں۔ کچھ فارم فائل سائز اور پکسل سائز دونوں مانگتے ہیں، اور دونوں پورے ہونے چاہییں۔</p>\n<h2 id=\"step-1-open-the-tool\">مرحلہ 1: 100KB ٹول کھولیں</h2>\n<p>براؤزر میں <a href=\"/ur/tasveer-compress-karein-100kb-tak/\">Compress Image to 100KB ٹول</a> کھولیں۔ کوئی اکاؤنٹ یا انسٹال نہیں چاہیے۔</p>\n<p>ٹول مکمل طور پر آپ کے آلے پر چلتا ہے۔ آپ کی تصویر مقامی طور پر پروسیس ہوتی ہے اور کبھی سرور پر اپ لوڈ نہیں ہوتی۔</p>\n<p>اگر آپ فون پر ہیں تو صفحہ اسی طرح کام کرتا ہے۔ اپ لوڈ والے حصے پر ٹیپ کریں اور اپنی گیلری سے تصویر چنیں۔</p>\n<h2 id=\"step-2-upload\">مرحلہ 2: تصویر اپ لوڈ کریں</h2>\n<p>فائل صفحے پر گھسیٹ دیں یا براؤز کرنے کے لیے ٹیپ کریں۔ JPG، PNG، WebP اور HEIC فائلیں قبول ہوتی ہیں، ہر ایک 25 MB تک۔</p>\n<p>اپنے پاس اعلیٰ ترین کوالٹی والا ورژن اپ لوڈ کریں۔ 12 میگا پکسل اصل کمپریسر کو چھوٹی کاپی سے کہیں زیادہ کام دیتا ہے۔</p>\n<p>بیچ کے لیے کئی فائلیں ایک ساتھ چنیں۔ ہر ایک 100KB تک کمپریس ہوتی ہے، اور آپ انہیں ZIP کے طور پر ایک ساتھ ڈاؤن لوڈ کرتے ہیں۔</p>\n<h2 id=\"step-3-choose-format\">مرحلہ 3: آؤٹ پٹ فارمیٹ چنیں</h2>\n<p>تصویروں کے لیے JPG محفوظ پہلے سے طے شدہ ہے۔ یہ ہر جگہ قبول ہوتا ہے اور 100KB پر صاف نتائج دیتا ہے۔</p>\n<p>اگر منزل اسے قبول کرے اور آپ تیز ترین نتیجہ چاہیں تو WebP چنیں۔ WebP اکثر اسی سائز پر کنارے تھوڑے صاف رکھتا ہے۔</p>\n<p>PNG صرف چپٹے رنگ، تیز لکیریں یا شفافیت والے گرافکس کے لیے رکھیں۔ PNG کے طور پر محفوظ تصویر کو 100KB تک پہنچنے میں مشکل ہو گی۔</p>\n<h2 id=\"step-4-run-compression\">مرحلہ 4: کمپریشن چلائیں</h2>\n<p>ٹول بائنری کوالٹی تلاش خود بخود چلاتا ہے۔ یہ کوالٹی سطحیں آزماتا ہے جب تک اسے اعلیٰ ترین سطح نہ ملے جو 100KB کے اندر فٹ ہو۔</p>\n<p>آپ کو کوالٹی فیصد چننے کی ضرورت نہیں۔ تلاش آپ کی مخصوص تصویر کے لیے بہترین عدد ڈھونڈتی ہے۔</p>\n<p>Under 100KB تصدیق دیکھیں۔ وہ بیج آپ کو بتاتا ہے کہ فائل حد سے گزر گئی اور استعمال کے لیے تیار ہے۔</p>\n<h2 id=\"step-5-preview\">مرحلہ 5: نتیجہ کا احتیاط سے پیش نظارہ دیکھیں</h2>\n<p>ڈاؤن لوڈ سے پہلے کمپریس شدہ تصویر کو مکمل سائز پر پیش نظارہ دیکھیں۔ چھوٹا تھمب نیل وہ مسائل چھپاتا ہے جو مکمل سائز پر واضح ہیں۔</p>\n<p>پہلے چہرے جانچیں۔ آنکھیں تیز رہنی چاہییں اور جلد ہموار لگنی چاہیے، دھبے والی یا پلاسٹک جیسی نہیں۔</p>\n<p>اگلا متن جانچیں۔ تصویر میں کوئی بھی الفاظ پڑھنے کے قابل رہنے چاہییں، خاص طور پر اسکرین شاٹ اور سرٹیفکیٹ میں۔</p>\n<h2 id=\"step-6-download\">مرحلہ 6: ڈاؤن لوڈ کریں اور منظم کریں</h2>\n<p>فائل ڈاؤن لوڈ کریں۔ اس کا نام اسے 100KB ورژن کے طور پر نشان زد کرے گا، اس لیے وہ اصل سے الجھے گا نہیں۔</p>\n<p>اپنے آلے پر فائل سائز جانچیں۔ یہ 100KB سے تھوڑا کم پڑھنا چاہیے، عام طور پر 98KB اور 99.9KB کے درمیان۔</p>\n<p>کمپریس شدہ کاپی کو اصل کے ساتھ رکھیں، اس کی جگہ نہیں۔ دونوں رکھنے کا مطلب ہے کہ آپ مختلف ترتیبات کے ساتھ ہمیشہ دوبارہ آزما سکتے ہیں۔</p>\n<h2 id=\"fixing-problems\">عام مسائل کا حل</h2>\n<p>اگر تصویر دھندلی لگے تو ماخذ شاید پہلے سے بہت چھوٹا تھا۔ بڑے اصل سے شروع کریں اور دوبارہ کمپریس کریں۔</p>\n<p>اگر ہدف چھوٹ گیا تو JPG پر جائیں اور اسکیلنگ کی اجازت دیں۔ یہ دو تبدیلیاں زیادہ تر ناکامیاں حل کرتی ہیں۔</p>\n<p>اگر رنگ غلط لگیں تو جانچیں کہ تصویر کا شفاف پس منظر تھا یا نہیں۔ شفاف PNG کو JPG میں بدلنے سے پس منظر بھر جاتا ہے، عام طور پر سفید سے۔</p>\n<h2 id=\"resume-photo-workflow\">ورک فلو: ریزیوم تصویر</h2>\n<p>سادہ پس منظر اور اچھی روشنی والی ہیڈ شاٹ لیں یا چنیں۔ صاف ماخذ پورا کام آسان بناتا ہے۔</p>\n<p>اسے 100KB ٹول میں اپ لوڈ کریں اور JPG فارمیٹ رکھیں۔ زیادہ تر ملازمت پورٹل اپنی قبول شدہ فارمیٹ میں JPG پہلے درج کرتے ہیں۔</p>\n<p>مکمل سائز پر چہرے کا پیش نظارہ دیکھیں۔ جانچیں کہ آنکھیں تیز ہیں اور پس منظر میں کوئی بینڈنگ نہیں۔</p>\n<h2 id=\"blog-thumbnail-workflow\">ورک فلو: بلاگ تھمب نیل</h2>\n<p>پوسٹوں کے سیٹ کے تمام تھمب نیل جمع کریں اور انہیں ایک بیچ کے طور پر اپ لوڈ کریں۔ ہر ایک 100KB تک کمپریس ہوتی ہے۔</p>\n<p>اگر آپ کا پلیٹ فارم اسے سپورٹ کرے تو بلاگ کے لیے WebP استعمال کریں۔ چھوٹا کوالٹی فائدہ درجنوں تصویروں میں جمع ہوتا ہے۔</p>\n<p>بیچ کے تین یا چار نتائج کا پیش نظارہ دیکھیں، صرف پہلا نہیں۔ ایک خراب نتیجہ اچھے نتائج میں چھپ سکتا ہے۔</p>\n<h2 id=\"phone-workflow\">ورک فلو: اپنے فون پر</h2>\n<p>اپنے موبائل براؤزر میں ٹول کھولیں اور اپ لوڈ والے حصے پر ٹیپ کریں۔ اپنی گیلری سے اصل تصویر چنیں۔</p>\n<p>آئی فون کی تصویریں HEIC فائلیں ہو سکتی ہیں۔ انہیں سیدھا اپ لوڈ کریں؛ ٹول کمپریشن کے دوران تبدیلی سنبھالتا ہے۔</p>\n<p>فون اسکرین پر نتیجہ کا پیش نظارہ دیکھیں، پھر زوم کرنے کے لیے چٹکی کریں۔ ڈاؤن لوڈ سے پہلے چہرہ اور کوئی بھی متن جانچیں۔</p>\n<h2 id=\"certificate-scans\">سرٹیفکیٹ اور دستاویز اسکین کم کرنا</h2>\n<p>سرٹیفکیٹ اسکین عام 100KB کام ہیں۔ وہ چھپا متن، مہریں اور کبھی چھوٹی تصویر ملاتے ہیں، جو انہیں سادہ پورٹریٹ سے مشکل بناتا ہے۔</p>\n<p>بہترین توازن کے لیے 300 DPI پر اسکین کریں۔ زیادہ ریزولوشن بڑی فائلیں بناتی ہیں جنہیں زیادہ سکڑانا پڑتا ہے، جبکہ کم ریزولوشن متن کو دھندلا کرتی ہے۔</p>\n<p>کمپریشن کے بعد سب سے چھوٹا متن پیش نظارہ دیکھیں۔ فوٹ نوٹ، رجسٹریشن نمبر اور دستخط پہلی چیزیں ہیں جنہیں نقصان پہنچتا ہے۔</p>\n<h2 id=\"comparing-results\">موازنہ منظر درست طریقے سے استعمال کرنا</h2>\n<p>موازنہ منظر آپ کا اصل کمپریس شدہ کاپی کے ساتھ دکھاتا ہے۔ اسے ہر بار استعمال کریں، کیونکہ آنکھ ساتھ ساتھ نقصان کو تیز پکڑتی ہے۔</p>\n<p>دونوں تصویروں میں ایک ہی جگہ دیکھیں۔ تفصیلی حصہ چنیں، جیسے بال یا چھوٹا متن، اور دونوں ورژن میں اسے غور سے دیکھیں۔</p>\n<p>چند بار آگے پیچھے ٹوگل کریں۔ ایک نظر میں نظر نہ آنے والے فرق اکثر تیزی سے بدلنے پر ظاہر ہوتے ہیں۔</p>\n<h2 id=\"auto-convert-png\">بڑی PNG خود بخود بدلنے کا اختیار</h2>\n<p>ٹول بڑی PNG خود بخود بدلنے کا اختیار دیتا ہے۔ جب یہ آن ہو تو PNG تصویریں کمپریشن کے دوران JPG یا WebP میں بدل جاتی ہیں۔</p>\n<p>تصویروں کے لیے اسے آن چھوڑ دیں۔ PNG تصویر تقریباً ہمیشہ کمپریشن ناکام ہونے کی وجہ ہے، اور تبدیلی اسے فوراً درست کرتی ہے۔</p>\n<p>شفافیت والے گرافکس کے لیے اسے بند کریں۔ شفاف PNG کو JPG میں بدلنے سے پس منظر سفید سے بھر جاتا ہے، جو شاید آپ چاہتے نہ ہوں۔</p>\n<h2 id=\"recompress-warning\">دوبارہ کمپریس وارننگ: اس کا مطلب کیا ہے</h2>\n<p>کبھی ٹول خبردار کرتا ہے کہ کمپریشن کے دوران فائل بڑھ گئی۔ یہ تب ہوتا ہے جب ان پٹ پہلے سے بہت کمپریس تھا۔</p>\n<p>بڑھی ہوئی فائل رکنے کی علامت ہے۔ اصل پہلے سے اس سے چھوٹا ہے جو ٹول بنائے گا، اس لیے اصل کو ویسا ہی استعمال کریں۔</p>\n<p>یہ وارننگ اکثر ویب سے ڈاؤن لوڈ شدہ فائلوں کے ساتھ آتی ہے۔ وہ پہلے سے اس سائٹ نے نچوڑ دی ہیں جس نے انہیں دیا۔</p>\n<h2 id=\"keeping-originals-safe\">اپنے اصل محفوظ رکھنا</h2>\n<p>کمپریشن یک طرفہ عمل ہے۔ ایک بار تفصیل پھینک دی جائے تو کوئی ٹول اسے واپس نہیں لا سکتا۔</p>\n<p>اصل کو کمپریس شدہ کاپیوں سے الگ فولڈر میں محفوظ کریں۔ واضح علیحدگی حادثاتی اوور رائٹ روکتی ہے۔</p>\n<p>اصل کا کہیں محفوظ بیک اپ رکھیں۔ کلاؤڈ فولڈر یا بیرونی ڈرائیو آپ کو بچاتا ہے اگر فون گم ہو جائے۔</p>\n<h2 id=\"team-workflows\">ٹیموں کے لیے 100KB ورک فلو</h2>\n<p>جو ٹیمیں ایک ساتھ شائع کرتی ہیں، انہیں مشترکہ معیار چاہیے۔ فی تصویر 100KB پر متفق ہونا ہر مصنف کو مختلف اندازہ لگانے سے روکتا ہے۔</p>\n<p>معیار لکھیں: فارمیٹ، سائز اور نام دینا۔ ٹیم وکی میں ایک صفحے کا رہنما سو چھوٹے سوالات روکتا ہے۔</p>\n<p>نئے شروع کرنے والوں کے ساتھ ٹول لنک شیئر کریں۔ 100KB کمپریسر کا بک مارک کمپریشن نظریہ کی طویل وضاحت سے زیادہ مفید ہے۔</p>\n<h2 id=\"alt-text-seo\">100KB پر Alt متن، فائل نام اور SEO</h2>\n<p>فائل سائز رفتار کو متاثر کرتا ہے، اور رفتار سرچ درجہ بندی کو متاثر کرتی ہے۔ 100KB تصویروں والا صفحہ تیزی سے لوڈ ہوتا ہے اور فی تصویر 2MB والے اسی صفحے سے بہتر درجہ پاتا ہے۔</p>\n<p>فائل نام بھی اہم ہیں۔ blue-cotton-shirt-100kb.jpg جیسا بیانی نام سرچ انجن کو بتاتا ہے کہ تصویر کیا دکھاتی ہے۔</p>\n<p>Alt متن سب سے اہم حصہ ہے۔ تصویر کو ایک جملے میں بیان کریں، اور وہ اہم تفصیل شامل کریں جسے تلاش کرنے والا ڈھونڈے گا۔</p>\n<h2 id=\"measuring-improvement\">کمپریشن کے بعد بہتری ناپنا</h2>\n<p>پہلے اور بعد کے اعداد فائدہ کو ٹھوس بناتے ہیں۔ چند تصویروں کے لیے اصل سائز اور کمپریس شدہ سائز نوٹ کریں اور ان کا موازنہ کریں۔</p>\n<p>عام فون تصویر 4MB سے 100KB تک گر جاتی ہے، 97 فیصد سے زیادہ بچت۔ یہ عدد ٹیم یا کلائنٹ کے ساتھ شیئر کرنے کے قابل ہے۔</p>\n<p>صفحہ رفتار بھی ناپیں۔ آٹھ سیکنڈ میں لوڈ ہونے والا صفحہ تصویریں 100KB تک کمپریس ہونے کے بعد دو سیکنڈ میں لوڈ ہو سکتا ہے۔</p>\n<h2 id=\"rounding-note\">فائل سائز اور گول کرنے پر نوٹ</h2>\n<p>فائل سائز بائٹ میں ناپے جاتے ہیں، مگر آلات انہیں گول کر کے دکھاتے ہیں۔ آپ کے فون پر 100KB پڑھنے والی فائل دراصل 100.4KB ہو سکتی ہے، جسے سخت پورٹل مسترد کر دے گا۔</p>\n<p>ٹول بالکل بائٹ گنتی ناپتا ہے اور حد سے تھوڑا نیچے ہدف رکھتا ہے۔ اپنے آلے کے گول عدد پر ٹول کے بیج پر بھروسہ کریں۔</p>\n<p>100KB اتنا اچھا کیوں کام کرتا ہے، اس کا پس منظر جاننے کے لیے <a href=\"/ur/blog/tasveer-100kb-tak-compress-karein-rehnumai/\">Compress Image to 100KB: Complete Guide</a> پڑھیں۔ تفصیلی فارمیٹ موازنہ کے لیے <a href=\"/ur/blog/100kb-tasveer-quality-aur-formats/\">100KB Image Quality: JPG vs PNG vs WebP at 100KB</a> دیکھیں۔ اگر سخت فارم کے لیے چھوٹی فائل چاہیے تو <a href=\"/ur/tasveer-compress-karein-50kb-tak/\">50KB کمپریسر</a> آزمائیں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"کیا تصویر کو بالکل 100KB تک کم کر سکتا ہوں؟","answer":"ٹول بالکل 100KB کی بجائے 100KB سے تھوڑا کم ہدف رکھتا ہے، عام طور پر 98 اور 99.9KB کے درمیان۔ یہ حفاظتی مارجن آپ کو نظاموں کے درمیان بائٹ گول کرنے کے فرق سے بچاتا ہے۔ اگر آپ کو بالکل اپنی مرضی کا عدد چاہیے تو ہدف فائل سائز کمپریسر استعمال کریں۔"},{"question":"تصویر کو 100KB تک کم کرنے کا بہترین فارمیٹ کون سا ہے؟","answer":"JPG محفوظ ترین ہمہ گیر انتخاب ہے اور ہر جگہ قبول ہوتا ہے۔ WebP اسی سائز پر تھوڑے صاف نتائج دیتا ہے جب منزل اسے قبول کرے۔ تصویروں کے لیے PNG سے بچیں، کیونکہ اسے بھاری ابعاد کٹوتی کے بغیر 100KB تک پہنچنے میں مشکل ہوتی ہے۔"},{"question":"کیا PNG اسکرین شاٹ کو متن دھندلا کیے بغیر 100KB تک کم کر سکتا ہوں؟","answer":"جی ہاں، زیادہ تر صورتوں میں۔ اسکرین شاٹ 100KB پر اچھی طرح کمپریس ہوتے ہیں، اور متن عام طور پر پڑھنے کے قابل رہتا ہے۔ اگر متن دھندلا ہو تو WebP آؤٹ پٹ آزمائیں یا بھاری کوالٹی کٹوتی کی بجائے چھوٹی ابعاد کمی کی اجازت دیں۔ ڈاؤن لوڈ سے پہلے نتیجہ زوم کر کے پیش نظارہ دیکھیں۔"},{"question":"ایک ساتھ کتنی تصویریں 100KB تک کم کر سکتا ہوں؟","answer":"آپ ایک بیچ میں کئی تصویریں شامل کر سکتے ہیں اور انہیں ZIP کے طور پر ایک ساتھ ڈاؤن لوڈ کر سکتے ہیں۔ کوئی روزانہ کوٹا نہیں۔ محدود میموری والے فون پر بہت بڑی فائلوں کے بہت بڑے بیچ سست ہو سکتے ہیں، اس لیے ضرورت پر انہیں چھوٹے گروپوں میں تقسیم کریں۔"},{"question":"کیا میری تصویر کو 100KB تک کم کرنے سے اس کا میٹا ڈیٹا حذف ہو جائے گا؟","answer":"جی ہاں، کمپریشن کے دوران کیمرہ EXIF ٹیگ اور GPS مقام ڈیٹا ہٹا دیے جاتے ہیں۔ یہ عام طور پر فائدہ ہے، خاص طور پر عوامی طور پر شیئر شدہ تصویروں کے لیے۔ تصویر کا مواد کمپریشن کے علاوہ ویسا ہی رہتا ہے۔"},{"question":"میری تصویر پہلے سے 90KB ہے۔ کیا پھر بھی اسے ٹول سے گزاروں؟","answer":"نہیں۔ اگر فائل پہلے سے آپ کی حد سے نیچے ہے تو اسے دوبارہ کمپریس کرنے سے بغیر فائدے کے صرف نقصان بڑھتا ہے۔ فائل کو ویسا ہی استعمال کریں۔ ٹول خود خبردار کرے گا اگر دوبارہ کمپریشن کے دوران فائل بڑھ جائے۔"}];
